mapper.select:
SELECT t.*
FROM sys_menu t
INNER JOIN sys_role_menu t1 ON t.id = t1.menu_id
WHERE p_id = #{pId,jdbcType=INTEGER}
AND t1.role_id = #{roleId,jdbcType=INTEGER}
ORDER BY t.display_order

SELECT 
FROM sys_menu
WHERE 1=1

	AND  name like CONCAT('%',#{name},'%')


	AND  menu_type = #{menuType}


	AND level = #{level}
